CREATE TABLE sfi_result AS SELECT a FROM (SELECT a FROM (SELECT a FROM (SELECT a FROM t1 NATURAL LEFT JOIN t1 WHERE (b,2) IS (SELECT 2 IN(2,2),2)) NATURAL LEFT FULL JOIN t1 WHERE (rowid,1)<=(CASE 5 WHEN 619 THEN 841 ELSE 3374391096 END,0) ORDER BY a ASC) NATURAL LEFT JOIN t1 WHERE (b,2) IS (SELECT 3 IN(3,3),3)) NATURAL LEFT FULL JOIN t1 WHERE (rowid,1)<=(CASE 5 WHEN 619 THEN 841 ELSE 3374391096 END,0) ORDER BY a ASC;